from pathlib import Path

BOT = Path('/app/bot.py')
text = BOT.read_text(encoding='utf-8')

# Install deterministic error capture at startup.
anchor = 'logger = logging.getLogger(__name__)\n'
insert = anchor + '\n# Deterministic admin diagnostics (never uses AI).\ntry:\n    from downloader.error_reporter import install as install_error_reporter\n    install_error_reporter()\nexcept Exception:\n    install_error_reporter = None\n'
if 'from downloader.error_reporter import install as install_error_reporter' not in text:
    if anchor not in text:
        raise SystemExit('logger anchor not found')
    text = text.replace(anchor, insert, 1)

# Add a dedicated current-error button to the existing admin keyboard.
ai_button = '''        [\n            InlineKeyboardButton(\n                "🤖 الذكاء الاصطناعي",\n                callback_data="admin_ai"\n            )\n        ],'''
error_button = ai_button + '''\n        [\n            InlineKeyboardButton(\n                "🧠 تقرير الخطأ الحالي",\n                callback_data="admin_current_error"\n            )\n        ],'''
if 'callback_data="admin_current_error"' not in text:
    if ai_button not in text:
        raise SystemExit('admin AI button anchor not found')
    text = text.replace(ai_button, error_button, 1)

# Add deterministic current-error view before the AI dashboard section.
marker = '# ============================================================\n# الذكاء الاصطناعي - لوحة الإدارة\n# ============================================================\n'
handler = '''# ============================================================\n# تقرير الخطأ الحالي - بدون AI\n# ============================================================\n\nasync def admin_current_error_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):\n    query = update.callback_query\n    await query.answer()\n    if update.effective_user.id != ADMIN_ID:\n        return\n\n    from downloader.error_reporter import latest\n    rows = latest(5)\n    if not rows:\n        text = (\n            "🧠 <b>تقرير الخطأ الحالي</b>\\n"\n            "━━━━━━━━━━━━━━━━━━\\n\\n"\n            "✅ لا توجد أخطاء مسجلة حتى الآن."\n        )\n    else:\n        row = rows[0]\n        created = str(row["created_at"]).replace("T", " ").split(".", 1)[0]\n        text = (\n            "🧠 <b>تقرير الخطأ الحالي</b>\\n"\n            "━━━━━━━━━━━━━━━━━━\\n\\n"\n            f"🔴 <b>السبب الرئيسي:</b> {html.escape(row['reason'])}\\n\\n"\n            f"🏷 <b>التصنيف:</b> <code>{html.escape(row['code'])}</code>\\n"\n            f"🕒 <b>الوقت:</b> {html.escape(created)}\\n"\n        )\n        if row["url"]:\n            text += f"🔗 <b>الرابط:</b> <code>{html.escape(row['url'])}</code>\\n"\n        text += (\n            "\\n📋 <b>آخر الأحداث:</b>\\n"\n            + "\\n".join(\n                f"• {html.escape(str(r['code']))} — {html.escape(str(r['reason']))}"\n                for r in rows[:5]\n            )\n        )\n\n    await query.edit_message_text(\n        text,\n        parse_mode="HTML",\n        reply_markup=InlineKeyboardMarkup([\n            [InlineKeyboardButton("🔄 تحديث التقرير", callback_data="admin_current_error")],\n            [InlineKeyboardButton("🏠 لوحة الإدارة", callback_data="admin_home")],\n        ])\n    )\n\n\n'''
if 'async def admin_current_error_callback' not in text:
    if marker not in text:
        raise SystemExit('AI section marker not found')
    text = text.replace(marker, handler + marker, 1)

# ------------------------------------------------------------
# Smart Search integration
# ------------------------------------------------------------
search_marker = '# ============================================================\n# استقبال الروابط\n# ============================================================\n'
search_handler = '''# ============================================================\n# Smart Search - بحث YouTube حتمي بدون AI\n# ============================================================\n\nSMART_SEARCH_TEXTS = {\n    "ar": {\n        "loading": "🔎 جاري البحث عن أفضل النتائج...\\n\\n⏳ لحظات من فضلك.",\n        "empty": "❌ لم يتم العثور على نتائج مناسبة.\\n\\nجرّب كلمات بحث أكثر تحديدًا.",\n        "title": "🔎 <b>نتائج البحث</b>\\n━━━━━━━━━━━━━━━━━━\\n\\n",\n        "item": "{index}. <b>{title}</b>{channel}{duration}{views}",\n        "selected": "🔗 تم اختيار النتيجة.\\n\\n👇 اختر نوع التحميل:",\n        "error": "❌ تعذر تنفيذ البحث حاليًا.\\n\\nجرّب مرة أخرى بعد قليل.",\n    },\n    "en": {\n        "loading": "🔎 Searching for the best results...\\n\\n⏳ Please wait.",\n        "empty": "❌ No suitable results were found.\\n\\nTry more specific keywords.",\n        "title": "🔎 <b>Search Results</b>\\n━━━━━━━━━━━━━━━━━━\\n\\n",\n        "item": "{index}. <b>{title}</b>{channel}{duration}{views}",\n        "selected": "🔗 Result selected.\\n\\n👇 Choose the download type:",\n        "error": "❌ Search is temporarily unavailable.\\n\\nPlease try again later.",\n    },\n    "tr": {\n        "loading": "🔎 En iyi sonuçlar aranıyor...\\n\\n⏳ Lütfen bekleyin.",\n        "empty": "❌ Uygun sonuç bulunamadı.\\n\\nDaha belirli anahtar kelimeler deneyin.",\n        "title": "🔎 <b>Arama Sonuçları</b>\\n━━━━━━━━━━━━━━━━━━\\n\\n",\n        "item": "{index}. <b>{title}</b>{channel}{duration}{views}",\n        "selected": "🔗 Sonuç seçildi.\\n\\n👇 İndirme türünü seçin:",\n        "error": "❌ Arama şu anda kullanılamıyor.\\n\\nLütfen tekrar deneyin.",\n    },\n    "de": {\n        "loading": "🔎 Suche nach den besten Ergebnissen...\\n\\n⏳ Bitte warten.",\n        "empty": "❌ Keine passenden Ergebnisse gefunden.\\n\\nVersuchen Sie spezifischere Suchbegriffe.",\n        "title": "🔎 <b>Suchergebnisse</b>\\n━━━━━━━━━━━━━━━━━━\\n\\n",\n        "item": "{index}. <b>{title}</b>{channel}{duration}{views}",\n        "selected": "🔗 Ergebnis ausgewählt.\\n\\n👇 Download-Typ auswählen:",\n        "error": "❌ Die Suche ist derzeit nicht verfügbar.\\n\\nBitte später erneut versuchen.",\n    },\n}\n\n\ndef _smart_search_text(language, key):\n    return SMART_SEARCH_TEXTS.get(language, SMART_SEARCH_TEXTS["ar"])[key]\n\n\ndef _smart_search_format_result(result):\n    parts = []\n    if result.channel:\n        parts.append(f"\\n👤 {html.escape(result.channel)}")\n    if result.duration is not None:\n        from downloader.smart_search import format_duration\n        duration = format_duration(result.duration)\n        if duration:\n            parts.append(f"\\n⏱ {duration}")\n    if result.views is not None:\n        from downloader.smart_search import format_views\n        views = format_views(result.views)\n        if views:\n            parts.append(f"\\n👁 {views}")\n    return "".join(parts)\n\n\nasync def smart_search_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):\n    query = update.callback_query\n    await query.answer()\n\n    user = update.effective_user\n    if not user:\n        return\n\n    register_user(user)\n    if is_banned(user.id):\n        await query.edit_message_text(TEXTS["ar"]["banned"])\n        return\n\n    language = get_language(user.id) or "ar"\n    try:\n        index = int(query.data.replace("smart_result_", ""))\n    except ValueError:\n        return\n\n    results = context.user_data.get("smart_search_results") or []\n    if index < 0 or index >= len(results):\n        await query.edit_message_text(TEXTS[language]["expired"])\n        return\n\n    selected = results[index]\n    url = selected.get("url") if isinstance(selected, dict) else None\n    if not url:\n        await query.edit_message_text(_smart_search_text(language, "error"))\n        return\n\n    try:\n        validate_public_http_url(url)\n    except ValueError:\n        await query.edit_message_text(_smart_search_text(language, "error"))\n        return\n\n    context.user_data["video_url"] = url\n\n    keyboard = InlineKeyboardMarkup([\n        [InlineKeyboardButton(TEXTS[language]["video_type"], callback_data="video_menu")],\n        [InlineKeyboardButton(TEXTS[language]["audio_type"], callback_data="audio_menu")],\n    ])\n    await query.edit_message_text(\n        _smart_search_text(language, "selected"),\n        reply_markup=keyboard,\n    )\n\n\nasync def handle_smart_search(text, update, context, language):\n    from downloader.smart_search import search\n\n    query_text = text.strip()\n    if not query_text:\n        return False\n\n    # Explicitly avoid treating ordinary URLs as search queries.\n    if re.match(r"^https?://", query_text, flags=re.IGNORECASE):\n        return False\n\n    status = await update.message.reply_text(\n        _smart_search_text(language, "loading")\n    )\n\n    try:\n        results = await search(query_text)\n    except Exception:\n        results = []\n\n    if not results:\n        await status.edit_text(_smart_search_text(language, "empty"))\n        return True\n\n    context.user_data["smart_search_results"] = [\n        {\n            "url": result.url,\n            "title": result.title,\n            "channel": result.channel,\n            "duration": result.duration,\n            "views": result.views,\n        }\n        for result in results\n    ]\n\n    keyboard = []\n    text_output = _smart_search_text(language, "title")\n    for index, result in enumerate(results):\n        text_output += _smart_search_format_result(result)\n        text_output += "\\n\\n"\n        keyboard.append([\n            InlineKeyboardButton(\n                f"{index + 1}️⃣ {result.title[:45]}",\n                callback_data=f"smart_result_{index}",\n            )\n        ])\n\n    await status.edit_text(\n        text_output[:3900],\n        parse_mode="HTML",\n        reply_markup=InlineKeyboardMarkup(keyboard),\n    )\n    return True\n\n\n'''
if 'async def smart_search_callback' not in text:
    if search_marker not in text:
        raise SystemExit('search insertion anchor not found')
    text = text.replace(search_marker, search_handler + search_marker, 1)

# Route non-URL text into Smart Search before the normal URL validation.
handle_anchor = '    url = text.strip()\n\n    try:\n        validate_public_http_url(url)\n'
handle_replacement = '''    url = text.strip()\n\n    if not re.match(r"^https?://", url, flags=re.IGNORECASE):\n        await handle_smart_search(\n            url,\n            update,\n            context,\n            language,\n        )\n        return\n\n    try:\n        validate_public_http_url(url)\n'''
if 'await handle_smart_search(' not in text:
    if handle_anchor not in text:
        raise SystemExit('handle_message URL anchor not found')
    text = text.replace(handle_anchor, handle_replacement, 1)

# Register Smart Search callback before the general download callbacks.
callback_anchor = '''    app.add_handler(\n        CallbackQueryHandler(\n            download_media,\n            pattern=r"^(video_|audio_|main_menu)"\n        )\n    )\n'''
callback_registration = '''    app.add_handler(\n        CallbackQueryHandler(\n            smart_search_callback,\n            pattern=r"^smart_result_[0-9]+$"\n        )\n    )\n\n''' + callback_anchor
if 'pattern=r"^smart_result_[0-9]+$"' not in text:
    if callback_anchor not in text:
        raise SystemExit('download callback anchor not found')
    text = text.replace(callback_anchor, callback_registration, 1)

BOT.write_text(text, encoding='utf-8')
print('runtime feature patch applied')
